code='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Fill the gaps between the outermost marked cells in each row and column.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != background]
        if cols:
            for c in range(cols[0], cols[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
        if rows:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
'''
